  "项目作用域当前不可选。Atlas 插件加载与扩展注册表是进程级共享；若将项目开关写成有效状态，会影响其他工作区。技能市场已安装到项目目录的技能显示其实际安装范围，但现有运行时只使用配置的默认工作区。": "Project scope is currently unavailable. Atlas plugin loading and the extension registry are shared at the process level; writing a project toggle as valid state would affect other workspaces. Skills installed to the project directory in the skill market show their actual install scope, but the current runtime only uses the configured default workspace.",
