  "用户级技能来源可连接到 Atlas Skill Market。扩展代码、提示词和主题目前只登记为元数据，不会安装或执行；本地技能目录检查只读取目录结构，注册表检查不会抓取远端内容。": "User-level skill sources can connect to Atlas Skill Market. Extension code, prompts, and themes are currently only registered as metadata and will not be installed or executed; local skill directory checks only read the directory structure, and registry checks do not fetch remote content.",
