  "llama.cpp 设置已保存。": "llama.cpp settings saved.",
  "已加入 Atlas 模型路由": "Added to Atlas model routing",
  "已在 Atlas 模型路由中": "Already in Atlas model routing",
  "llama.cpp 已启动，服务仍在加载；可稍后刷新状态。": "llama.cpp started; the service is still loading; refresh status later.",
  "已停止 Atlas 启动的 llama.cpp 服务。": "Stopped the llama.cpp service started by Atlas.",
  "Ollama 本地模型": "Ollama local models",
  "只连接本机 127.0.0.1:11434，不扫描局域网。下载只会在你按“下载”后请求本机 Ollama；Ollama 随后从其模型库拉取。 添加到 Atlas 只登记 OpenAI-compatible 本机路由，不修改 provider 密钥，也不会自动切换当前模型。": "Connect only to local 127.0.0.1:11434; do not scan the LAN. Downloads request the local Ollama only after you press \"Download\"; Ollama then pulls from its model library. Adding to Atlas only registers an OpenAI-compatible local route; it does not modify provider keys or automatically switch the current model.",
  "Ollama 模型名称": "Ollama model name",
