  "llama.cpp 服务管理": "llama.cpp service management",
  "llama.cpp 服务": "llama.cpp service",
  "健康": "Healthy",
  "启动中 / 外部实例": "Starting / external instance",
  "使用本机已安装的 llama-server 和 GGUF 文件；Atlas 仅绑定 127.0.0.1，不下载二进制或模型。启动后可将模型注册到模型列表。": "Use the locally installed llama-server and GGUF files; Atlas binds only to 127.0.0.1 and does not download binaries or models. After startup, the model can be registered in the model list.",
  "llama-server 可执行文件路径": "llama-server executable path",
