  "主配置": "Main configuration",
  "界面设置": "Interface settings",
  "当前生效": "Currently active",
  "备份": "Backup",
  "有未保存的修改": "There are unsaved changes",
  "Atlas 主体的": "Atlas main configuration",
  "。保存前会检查写法，旧版本自动备份；大部分设置下一轮对话生效，模型网关、工具服务器等启动项重启 Atlas 后生效。": ". Syntax is checked before saving, and the old version is automatically backed up; most settings take effect in the next conversation round, while startup items such as the model gateway and tool servers take effect after restarting Atlas.",
  "你在界面里改过的设置（模型、密钥、偏好等），优先级高于 atlas.toml。里面有密钥，别截图外传。": "Settings you have changed in the interface (models, keys, preferences, etc.) take precedence over atlas.toml. It contains keys, so do not screenshot or share it.",
  "专家模式开着：这里是 atlas.toml 叠上专家配置之后、Atlas 实际在用的结果。": "Expert mode is on: this shows the result Atlas is actually using after layering expert configuration on top of atlas.toml.",
  "普通模式：Atlas 实际在用的就是 atlas.toml。": "Normal mode: what Atlas is actually using is atlas.toml.",
  "只读。": "Read-only.",
  "每次保存前自动留一份，各保留最近 30 份。恢复也会先把当前版本备份。": "A copy is automatically kept before each save, with the latest 30 kept for each. Restoring also backs up the current version first.",
  "还没有备份，保存一次后会出现在这里。": "No backups yet; they will appear here after you save once.",
