  "这里只显示 MCP 服务返回的 resources/list 内容。工具输入参数不会展示；服务未实现资源接口、断开或读取失败时会标明状态。": "This only shows the resources/list content returned by MCP services. Tool input parameters are not displayed; if a service does not implement the resource interface, is disconnected, or fails to read, the status will be indicated.",
