  "当前 API 支持添加、重启和移除已连接的服务；配置读取、编辑和启停接口尚未提供。失败或停用的服务可在依赖检查中查看状态。": "The current API supports adding, restarting, and removing connected services; configuration read, edit, and enable/disable interfaces are not yet available. Failed or disabled services can be checked for status in dependency checks.",
