  "在同一局域网的手机浏览器查看并继续 Atlas 会话，处理待审批操作。临时链接有效 8 小时，密钥只在链接片段中传递。": "View and continue Atlas sessions from a phone browser on the same LAN, and handle pending approvals. Temporary link valid for 8 hours; the key is passed only in the link fragment.",
