  "自托管远端任务（SSH / ZeroTier）": "Self-hosted remote task (SSH / ZeroTier)",
  "Atlas 云端执行服务当前不可用。任务由本机 Atlas 通过 SSH 派发到你的机器；SSH 密钥、端口和主机验证沿用本机 ~/.ssh/config，不会上传或复制到 Atlas。": "The Atlas cloud execution service is currently unavailable. Tasks are dispatched from local Atlas to your machine via SSH; SSH keys, ports, and host verification use your local ~/.ssh/config and are never uploaded or copied to Atlas.",
