  "会话迁移快照": "Session migration snapshot",
  "保存最近 80 条 user/assistant 历史、工作区 URI、Git status 与相对 HEAD 的补丁到本机 Atlas 数据目录，之后可将快照关联到任务。不会复制 SSH 私钥或 Atlas 凭据；任务在所选 SSH 用户权限下运行。": "Save the latest 80 user/assistant history entries, workspace URI, Git status, and patch relative to HEAD to the local Atlas data directory; the snapshot can then be linked to tasks. SSH private keys and Atlas credentials are not copied; tasks run with the permissions of the selected SSH user.",
  "会话 ID（留空保存工作区快照）": "Session ID (leave empty to save workspace snapshot)",
  "保存快照": "Save snapshot",
  "条历史 · 工作区 diff": "history entries · workspace diff",
