  "暂无日志": "No logs yet",
  "此 attempt 没有检测到 Git diff": "No Git diff detected for this attempt",
  "审查后应用到本机工作区": "Apply to local workspace after review",
  "当前筛选条件下没有远端任务。": "No remote tasks under current filters.",
  "凭据与权限边界：本机 SSH config/agent 负责 HostName、Port、User、IdentityFile 和 known_hosts；Atlas 本地数据只保存环境标签与路径、任务日志、补丁和会话快照。远端命令以所选 SSH 用户权限执行，Atlas 不另加审批限制。计划任务需要本机 Atlas 后端保持运行；关机时不会在云端继续运行。": "Credentials and permission boundaries: local SSH config/agent handles HostName, Port, User, IdentityFile, and known_hosts; Atlas local data stores only environment tags and paths, task logs, patches, and session snapshots. Remote commands run with the permissions of the selected SSH user, with no additional approval restrictions from Atlas. Scheduled tasks require the local Atlas backend to stay running; they will not continue in the cloud when powered off.",
  "估算费用上限必须是 0.001 到 100000 之间、最多 4 位小数的金额。": "Estimated cost cap must be an amount between 0.001 and 100000 with at most 4 decimal places.",
  "设置用户级轮数上限。它作用于新运行，不会更改已经开始的运行。": "Set a user-level turn limit. It applies to new runs and does not change runs that have already started.",
  "用户轮数上限": "User turn limit",
  "引擎上限：": "Engine limit:",
  "轮。留空使用引擎默认值；填入更小数值会限制每次新运行的主循环轮数。": "turns. Leave blank to use the engine default; entering a smaller value limits the main loop turns per new run.",
