  "无法打开系统浏览器": "Cannot open system browser",
  "已在浏览器打开 Google 登录；完成授权后此处会自动连接": "Google sign-in opened in browser; connection will complete automatically after authorization",
  "已删除本机 Google OAuth token": "Deleted local Google OAuth token",
  "任务与外部集成入口": "Tasks and external integrations",
  "这里汇总 Atlas 当前可用的入口。GitHub PR 使用本机工作区和已安装的 gh CLI；Slack 作为本机 Gateway 渠道运行；自动化由本机调度器执行。": "This page summarizes the entry points currently available in Atlas. GitHub PRs use the local workspace and installed gh CLI; Slack runs as a local Gateway channel; automation is executed by the local scheduler.",
  "Google Drive 与 Gmail（只读）": "Google Drive and Gmail (read-only)",
  "登录后搜索文件或邮件，并由你逐条选择导入当前对话。OAuth refresh token 加密范围仅为本机数据目录；应用申请 Drive readonly 与 Gmail readonly 权限。": "After signing in, search files or emails and select items to import into the current conversation one by one. OAuth refresh token encryption is scoped to the local data directory only; the app requests Drive readonly and Gmail readonly scopes.",
  "首次使用：在 Google Cloud Console 启用 Drive API 与 Gmail API，创建 OAuth 客户端 ID（桌面应用），将 Client ID 粘贴到此处，并确保测试用户包含你的 Google 账号。Atlas 使用 PKCE loopback 登录，不需要输入或保存 client secret。": "First use: enable the Drive API and Gmail API in Google Cloud Console, create an OAuth client ID (desktop app), paste the Client ID here, and make sure your Google account is included as a test user. Atlas uses PKCE loopback sign-in and does not require entering or storing a client secret.",
  "Google 桌面应用 OAuth Client ID": "Google desktop app OAuth Client ID",
