  "查看工作区变更、创建 PR 并在 Atlas Code 页面跟进。需要本机 git/gh 登录状态。": "View workspace changes, create PRs, and follow up on the Atlas Code page. Requires local git/gh sign-in status.",
  "打开 Code": "Open Code",
  "配置 Slack Socket Mode 机器人凭据，连接本机 Atlas Gateway。可用性取决于可选依赖和凭据。": "Configure Slack Socket Mode bot credentials to connect to the local Atlas Gateway. Availability depends on optional dependencies and credentials.",
