  "Atlas 云执行服务": "Atlas cloud execution service",
  "当前没有 Atlas 云端执行服务。上方自托管任务可通过 SSH 在你的另一台电脑执行；本机自动化仍由本机调度器运行。": "There is currently no Atlas cloud execution service. The self-hosted tasks above can execute on your other computer via SSH; local automation is still run by the local scheduler.",
