  "只读探索并先提交计划，批准后再执行。": "Read-only exploration with a plan submitted first; execute after approval.",
  "只能查看，不能修改。": "View only, cannot modify.",
  "远程工作区暂不支持 Docker 沙箱。": "Docker sandbox is not yet supported for remote workspaces.",
  "Docker 沙箱只支持 Atlas Agent；先在运行方式设置中切回 Atlas。": "Docker sandbox only supports Atlas Agent; switch back to Atlas in the run mode settings first.",
  "允许目录必须是本机绝对路径；远程 SSH 工作区不能在这里添加本机允许目录。": "Allowed directories must be local absolute paths; remote SSH workspaces cannot add local allowed directories here.",
  "附加目录必须是本机绝对路径或 ssh:// 地址。": "Additional directories must be local absolute paths or ssh:// addresses.",
  "这个目录已是主工作区或已在附加目录列表中。": "This directory is already the primary workspace or is already in the additional directories list.",
  "每个对话最多添加 5 个附加目录。": "Each conversation can add at most 5 additional directories.",
  "已撤销此工作区的规则信任；正在运行的任务不受影响，下次运行会再次询问。": "Revoked rule trust for this workspace; running tasks are unaffected, and the next run will ask again.",
  "此工作区当前没有已保存的信任。": "This workspace currently has no saved trust.",
  "工作区安全设置": "Workspace security settings",
  "规则信任、会话权限和命令隔离。": "Rule trust, session permissions, and command isolation.",
  "AGENTS.md / CLAUDE.md 规则信任": "AGENTS.md / CLAUDE.md rule trust",
  "运行前会检查工作区的 AGENTS.md、CLAUDE.md、.atlas/rules.md、.atlas/NOTES.md 和支持的 Agent 规则文件。检测到未信任规则时，对话中会出现“信任并加载”或“不加载，继续”的确认卡。接受后，该工作区的信任会保存在本机；拒绝只会跳过这次运行的规则文件。": "Before running, the workspace's AGENTS.md, CLAUDE.md, .atlas/rules.md, .atlas/NOTES.md, and supported Agent rule files are checked. When untrusted rules are detected, a confirmation card appears in the conversation with \"Trust and load\" or \"Don't load, continue\". If accepted, the workspace trust is saved locally; declining only skips the rule files for this run.",
  "工作区规则可以给 Atlas 任意指令；只信任你了解的项目。状态按本机工作区信任表读取，撤销后只影响之后的运行。当前工作区：": "Workspace rules can give Atlas arbitrary instructions; only trust projects you understand. Status is read from the local workspace trust table; revoking only affects subsequent runs. Current workspace:",
  "尚未设置": "Not set yet",
  "先为此对话选择工作区。": "Select a workspace for this conversation first.",
  "远程 SSH 工作区的信任仍由运行时确认卡管理。": "Trust for remote SSH workspaces is still managed by runtime confirmation cards.",
  "正在读取本机信任状态…": "Reading local trust status…",
  "无法读取工作区信任状态。": "Unable to read workspace trust status.",
  "撤销信任": "Revoke trust",
  "读取或撤销信任失败：": "Failed to read or revoke trust:",
  "文件工具允许目录": "File tool allowed directories",
  "当前未设置目录 allowlist；文件工具不受额外路径列表限制。设置后，文件工具只能访问主工作区和列出的目录。": "No directory allowlist is currently set; file tools are not restricted by an additional path list. Once set, file tools can only access the primary workspace and the listed directories.",
  "此列表只检查工具调用中明确提供的路径参数，不是操作系统沙箱；命令本身的文件访问需用 Docker 隔离。": "This list only checks explicit path parameters in tool calls; it is not an OS sandbox. File access by the commands themselves requires Docker isolation.",
  "主工作区：": "Primary workspace:",
  "未设置；当前没有隐含的主工作区根目录": "Not set; there is currently no implicit primary workspace root",
  "移除允许目录": "Remove allowed directory",
  "目前只允许主工作区。": "Currently only the primary workspace is allowed.",
  "本机绝对路径": "Local absolute path",
  "远程工作区不支持添加本机允许目录": "Remote workspaces do not support adding local allowed directories",
  "本机绝对路径，例如 D:\\Projects\\Atlas": "Local absolute path, e.g. D:\\Projects\\Atlas",
  "允许目录": "Allowed directories",
  "仅限主工作区": "Primary workspace only",
  "恢复不限目录": "Restore unrestricted directories",
  "附加工作区目录": "Additional workspace directories",
  "附加目录会加入新运行的工作区上下文，并检查其中的支持规则文件；未信任的规则仍会由运行时确认卡询问。开启上方 allowlist 时，本机附加目录也会并入允许路径。": "Additional directories are added to the workspace context of new runs, and their supported rule files are checked; untrusted rules will still be prompted by runtime confirmation cards. When the allowlist above is enabled, local additional directories are also merged into allowed paths.",
  "移除附加目录": "Remove additional directory",
  "附加目录路径": "Additional directory path",
  "本机绝对路径或 ssh://user@host/path": "Local absolute path or ssh://user@host/path",
  "添加目录": "Add directory",
  "目录修改会自动保存到当前对话，只影响后续启动的运行；清空 allowed_paths 会恢复默认的不限制路径列表。服务端检查绝对路径和 SSH 地址格式，但不验证本机目录是否存在。": "Directory changes are saved automatically to the current conversation and only affect subsequently started runs; clearing allowed_paths restores the default unrestricted path list. The server checks absolute path and SSH address formats but does not verify that local directories exist.",
  "后续运行的工具权限": "Tool permissions for subsequent runs",
  "设置保存在当前对话，只影响之后启动的运行。": "Settings are saved to the current conversation and only affect subsequently started runs.",
  "当前使用外部 Agent。外部 Agent 不经过 Atlas 的工具确认；选择任何非“完全访问”模式会按现有行为自动切回 Atlas。": "An external Agent is currently in use. External Agents do not go through Atlas tool confirmation; selecting any mode other than \"Full access\" will automatically switch back to Atlas per existing behavior.",
  "Docker 命令隔离": "Docker command isolation",
  "容器设置保存在当前对话，只对之后的运行生效；容器联网默认关闭。": "Container settings are saved to the current conversation and only take effect for subsequent runs; container networking is off by default.",
  "允许容器联网": "Allow container networking",
  "关闭 Docker 隔离": "Disable Docker isolation",
  "联网权限会开放给容器内运行的命令；只在安装依赖或访问网络资源时开启。": "Network access will be granted to commands running inside the container; enable only when installing dependencies or accessing network resources.",
  "当前命令在本机运行。": "Current commands run locally.",
  "启用 Docker 隔离": "Enable Docker isolation",
