  "群策略设为“仅允许名单”且群名单为空时，运行时回退到私聊允许名单；两者都空时，现有运行时会放行。提及检查使用事件的 is_mention 或 reply_to_event_id。配对门控目前没有自动申请 / 批准流程。": "When the group policy is set to \"Allowlist only\" and the group allowlist is empty, runtime falls back to the DM allowlist; if both are empty, the existing runtime allows through. Mention checks use the event's is_mention or reply_to_event_id. Pairing gating currently has no automatic request / approval flow.",
