  "我们用「规格驱动」的方式做一个功能。先只写需求文档，不要写代码、不要改其他文件。\n\n功能描述：__U26_SLOT_0__\n\n把需求写到 `__U26_SLOT_1__/requirements.md`：\n- 开头一段话说清楚目标和不做什么；\n- 然后是用户故事，每条「作为…，我想…，以便…」，下面列验收标准，用「当…时，系统应当…」的句式，可以逐条验证；\n- 最后列出你不确定、需要我拍板的问题。\n写完告诉我路径，等我确认。": "Let's build a feature in a \"spec-driven\" way. For now, only write the requirements document—do not write code and do not modify other files.\n\nFeature description: __U26_SLOT_0__\n\nWrite the requirements to `__U26_SLOT_1__/requirements.md`:\n- Start with a paragraph clarifying the goal and what is out of scope;\n- Then user stories, each in the form \"As a…, I want…, so that…\", with acceptance criteria listed below using the \"When…, the system should…\" format that can be verified item by item;\n- Finally, list the questions you are unsure about and need me to decide.\nWhen done, tell me the path and wait for my confirmation.",
  "读 `__U26_SLOT_0__/requirements.md`，再看一下这个项目现有的代码结构，然后写设计文档 `__U26_SLOT_1__/design.md`：整体方案、要改或新增的模块和文件、数据结构和接口、错误处理、测试方案，以及考虑过但没选的方案和原因。只写设计，不要改代码。写完等我确认。": "Read `__U26_SLOT_0__/requirements.md`, then look at the project's existing code structure, and write the design document `__U26_SLOT_1__/design.md`: overall approach, modules and files to change or add, data structures and interfaces, error handling, test plan, and alternatives considered but not chosen with reasons. Only write the design; do not change code. When done, wait for my confirmation.",
  "读 `__U26_SLOT_0__/requirements.md` 和 `__U26_SLOT_1__/design.md`，把实现拆成任务清单写到 `__U26_SLOT_2__/tasks.md`：每项一行，用 `- [ ] ` 开头，按执行顺序排；每项小到一次能做完并验证，写明要改的文件和怎么验证，并注明对应哪几条需求。只写清单，不要开始实现。": "Read `__U26_SLOT_0__/requirements.md` and `__U26_SLOT_1__/design.md`, and break the implementation into a task list written to `__U26_SLOT_2__/tasks.md`: one item per line, starting with `- [ ] `, ordered by execution sequence; each item small enough to complete and verify in one go, specifying the files to change and how to verify, and noting which requirements it corresponds to. Only write the list; do not start implementing.",
  "按 `__U26_SLOT_0__` 下的规格执行任务清单第 __U26_SLOT_1__ 项：「__U26_SLOT_2__」。\n先读 requirements.md、design.md 和 tasks.md，只做这一项，做完按清单里写的方法验证；通过后把 tasks.md 里这一项的 `- [ ]` 改成 `- [x]`。最后说明改了什么、怎么验证的。如果发现设计有问题，停下来告诉我，不要自行扩大范围。": "Execute task list item __U26_SLOT_1__ under the spec in `__U26_SLOT_0__`: \"__U26_SLOT_2__\".\nFirst read requirements.md, design.md, and tasks.md; do only this item, and verify it using the method described in the list; once it passes, change `- [ ]` to `- [x]` for this item in tasks.md. Finally, explain what you changed and how you verified it. If you find a design problem, stop and tell me; do not expand the scope on your own.",
  "关闭 __U26_SLOT_0__ 会结束该 PowerShell 终端及其前台进程。继续吗？": "Closing __U26_SLOT_0__ will end that PowerShell terminal and its foreground processes. Continue?",
