  "原消息已完整发送，标记内容不会从消息正文移除。检查或编辑后再确认写入记忆库；“仅发送”会放弃保存。": "The original message was sent in full, including its marker. Review or edit the content before confirming it to memory; choose “Send only” to discard the save.",
