  "Atlas 的记录": "Atlas's notes",
  "语法：单行 `# 记忆内容` 或 `#记住：记忆内容`；后续非空行属于同一条，空行开始新段。代码围栏中的 # 不触发；行首写 `\\#` 表示普通文本。": "Syntax: use `# memory content` or `#记住：memory content` on a line. Following non-empty lines belong to the same entry; a blank line starts another. Markers inside code fences are ignored; start a line with `\\#` for ordinary text.",
  "仅发送，不保存": "Send only, don't save",
  "正在保存…": "Saving…",
  "确认保存记忆": "Confirm and save memory",
  "按 Enter 发送，Shift 加 Enter 换行；建议列表可用上下方向键选择、Tab 补全，Escape 关闭。行首 `# 内容` 或 `#记住：内容` 会在消息照常发送后打开记忆审阅；代码围栏内不触发，写 `\\#` 可表示普通文本。选中文字后按 Alt 加 Shift 加 A，可将选中文字放入消息草稿。": "Press Enter to send and Shift+Enter for a new line. Browse suggestions with the arrow keys, complete with Tab, and dismiss with Escape. A line starting with `# content` or `#记住：content` opens a memory review after the message is sent; code fences are ignored, and `\\#` escapes the marker. Select text and press Alt+Shift+A to add it to the draft.",
